// Renders the leaderboard tables: <div data-leaderboard="many_to_one"></div>.
// The data comes from leaderboard-data.js, generated by `python -m discophon.leaderboard build`.
(function () {
  function el(tag, props, children) {
    const node = Object.assign(document.createElement(tag), props);
    node.append(...(children || []));
    return node;
  }

  function mean(xs) {
    return xs.reduce((a, b) => a + b, 0) / xs.length;
  }

  function std(xs) {
    const m = mean(xs);
    return xs.length > 1 ? Math.sqrt(xs.reduce((a, b) => a + (b - m) ** 2, 0) / (xs.length - 1)) : 0;
  }

  function init(root, data) {
    const track = root.dataset.leaderboard;
    const metrics = data.tracks[track];
    const rows = data.rows.filter((r) => r.track === track);
    const models = data.models.filter((m) => m.tracks.includes(track));

    const splitSelect = el("select", {}, [
      el("option", { value: "dev", textContent: "Dev languages" }),
      el("option", { value: "test", textContent: "Test languages", selected: true }),
    ]);
    const langSelect = el("select");
    const tbody = el("tbody");
    const header = metrics.map((m) => el("th", { textContent: m.label + (m.lower_is_better ? " ↓" : " ↑") }));
    root.replaceChildren(
      el("div", { className: "dlb-controls" }, [
        el("label", {}, ["Split", splitSelect]),
        el("label", {}, ["Language", langSelect]),
      ]),
      el("div", { className: "dlb-scroll" }, [
        el("table", { className: "dlb-table" }, [
          el("thead", {}, [el("tr", {}, [el("th", { textContent: "Model" }), ...header])]),
          tbody,
        ]),
      ])
    );

    function populateLanguages() {
      const split = splitSelect.value;
      const previous = langSelect.value;
      langSelect.replaceChildren(
        el("option", { value: "", textContent: "Average over " + split + " languages" }),
        ...data.languages
          .filter((l) => l.split === split)
          .map((l) => el("option", { value: l.iso, textContent: l.name }))
      );
      langSelect.value = [...langSelect.options].some((o) => o.value === previous) ? previous : "";
    }

    // Score of one model for one metric: a single language, or the average over the split
    // (only when every language of the split has a score).
    function score(modelRows, metric, split, language) {
      if (language) {
        const row = modelRows.find((r) => r.metric === metric && r.language === language);
        return row ? { value: row.score } : null;
      }
      const langs = data.languages.filter((l) => l.split === split).map((l) => l.iso);
      const values = langs.map((iso) => modelRows.find((r) => r.metric === metric && r.language === iso));
      if (values.some((r) => !r)) return null;
      const xs = values.map((r) => r.score);
      return { value: mean(xs), std: std(xs) };
    }

    function render() {
      const split = splitSelect.value;
      const language = langSelect.value;
      tbody.replaceChildren();
      for (const duration of data.durations) {
        const table = models
          .map((model) => {
            const modelRows = rows.filter((r) => r.model === model.key && r.duration === duration.key);
            const scores = metrics.map((m) => score(modelRows, m.key, split, language));
            return { model, layer: modelRows.length ? modelRows[0].layer : null, scores };
          })
          .filter((entry) => entry.layer !== null);
        if (!table.length) continue;
        const best = metrics.map((m, i) => {
          const values = table.map((e) => e.scores[i]).filter(Boolean).map((s) => s.value);
          return m.lower_is_better ? Math.min(...values) : Math.max(...values);
        });
        tbody.append(group("dlb-group", duration.label));
        for (const category of data.categories) {
          const entries = table.filter((e) => e.model.category === category.key);
          if (!entries.length) continue;
          tbody.append(group("dlb-subgroup", category.label));
          for (const { model, layer, scores } of entries) {
            const name = el("td", {}, [
              el("a", { href: model.url, target: "_blank", rel: "noopener", title: model.description, textContent: model.label }),
              " (L" + layer + ") ",
              el("a", { href: model.artifacts, target: "_blank", rel: "noopener", className: "dlb-files", textContent: "files" }),
            ]);
            const cells = scores.map((s, i) => {
              if (!s) return el("td", { textContent: "N/A" });
              const td = el("td", { textContent: s.value.toFixed(2) });
              if (s.std !== undefined) td.append(" ", el("span", { className: "dlb-std", textContent: "±" + s.std.toFixed(2) }));
              if (s.value === best[i]) td.classList.add("dlb-top");
              return td;
            });
            tbody.append(el("tr", {}, [name, ...cells]));
          }
        }
      }
    }

    function group(className, label) {
      return el("tr", { className }, [el("th", { colSpan: 1 + metrics.length, textContent: label })]);
    }

    splitSelect.addEventListener("change", () => {
      populateLanguages();
      render();
    });
    langSelect.addEventListener("change", render);
    populateLanguages();
    render();
  }

  // document$ replays the current page on subscription and emits again after every instant navigation.
  document$.subscribe(() => {
    const data = window.DISCOPHON_LEADERBOARD;
    if (!data) return;
    document.querySelectorAll("[data-leaderboard]").forEach((root) => init(root, data));
  });
})();
